Just to add to this, can we modify this function in array_api.py as such to accomodate for the older version of NumPy if used?

```python
def _convert_to_numpy(array, xp):
    """Convert X into a NumPy ndarray on the CPU."""
    if _is_xp_namespace(xp, "torch"):
        return array.cpu().numpy()
    elif _is_xp_namespace(xp, "cupy"):  # pragma: nocover
        return array.get()
    elif _is_xp_namespace(xp, "array_api_strict"):
        return numpy.asarray(xp.asarray(array, device=xp.Device("CPU_DEVICE")))

    try:
        return numpy.asarray(array)
    except TypeError:
        # Some array libraries (e.g. DPNP) deliberately reject implicit
        # conversions through `__array__`. In that case, try an explicit
        # conversion path through DLPack when available.
        if hasattr(array, "__dlpack__"):
            try:
                return numpy.from_dlpack(array, device="cpu")
            except TypeError:
                # NumPy < 2.0 does not accept the `device` keyword.
                return numpy.from_dlpack(array)
        raise

```

and its corresponding function in test_array_api.py

```python
def test_convert_to_numpy_dlpack_fallback():
    #this function will check convert_to_numpy fallback when implicit NumPy conversion is disabled.

    class _NoImplicitNumpyConversionArray:
        def __init__(self, array):
            self._array = numpy.asarray(array)

        def __array__(self, dtype=None, copy=None):
            raise TypeError(
                "Implicit conversion to a NumPy array is not allowed. "
                "Please use `.asnumpy()` to construct a NumPy array explicitly."
            )

        def __dlpack__(self, stream=None):
            return self._array.__dlpack__(stream=stream)

        def __dlpack_device__(self):
            return self._array.__dlpack_device__()

    if not hasattr(numpy, "from_dlpack"):
        pytest.skip("NumPy does not provide from_dlpack")

    array = _NoImplicitNumpyConversionArray([1, 2, 3])
    result = _convert_to_numpy(array, xp=numpy)
    assert_array_equal(result, numpy.asarray([1, 2, 3]))
```
